record.content:
#import "/_fx/ui.typ": *

#let data = json("data.json")
#let theme = fx-theme(preset: "swiss-minimal", overrides: (primary: rgb("#1d4ed8"), accent: rgb("#0f766e"), font-heading: "Open Sans", font-body: "Open Sans", density: "compact"))

#show: fx-doc.with(
  theme: theme,
  paper: "a4",
  flipped: false,
  margin: (top: 1.2cm, bottom: 1.2cm, left: 1.5cm, right: 1.5cm),
  footer: (left: fx-str(fx-get(data, "establishment.name")) + " — " + fx-str(fx-get(data, "establishment.address")), center: fx-str(fx-get(data, "establishment.phone")) + " • " + fx-str(fx-get(data, "establishment.website")), right: "", show-page-numbers: true),
)

#fx-block(id: "doc-header")[
  #fx-header(
    title: fx-str(fx-get(data, "document.title")),
    eyebrow: fx-str(fx-get(data, "establishment.name")) + " — " + fx-str(fx-get(data, "establishment.category")),
    subtitle: fx-str(fx-get(data, "document.subtitle")),
    badge: fx-str(fx-get(data, "document.service")),
    align-mode: "center",
    meta: (
      (label: "Jour", value: fx-str(fx-get(data, "document.dayOfWeek"))),
      (label: "Date", value: fx-date(fx-get(data, "document.date"))),
      (label: "Référence", value: fx-str(fx-get(data, "document.reference"))),
    ),
    theme: theme,
  )
]

#if fx-truthy(fx-get(data, "document.summary")) [
  #fx-block(id: "doc-intro")[
    #block(width: 100%)[#align(center)[#text(size: 9.5pt, style: "italic", fill: theme.muted)[#(fx-str(fx-get(data, "document.summary")))]]]
  ]
]

#fx-block(id: "establishment-info")[
  #fx-kv-grid(
    columns: 3,
    items: (
      (label: "Horaires", value: fx-str(fx-get(data, "establishment.openingHours"))),
      (label: "Réservations", value: fx-str(fx-get(data, "establishment.phone"))),
      (label: "Adresse", value: fx-str(fx-get(data, "establishment.address"))),
    ),
    theme: theme,
  )
]

#fx-block(id: "intro-divider")[
  #fx-divider(style: "accent", theme: theme)
]

#fx-block(id: "menu-columns")[
  #fx-columns(
    widths: (1fr, 1.25fr,),
    gap: 10pt,
    [
      #fx-block(id: "menu-left-col")[
        #fx-card(theme: theme)[
          #if fx-truthy(fx-get(data, "menu.dailySpecials")) [
            #fx-block(id: "specials-heading")[
              #block(width: 100%, above: 10pt, below: 5pt)[
                #stack(dir: ltr, spacing: 6pt, rect(width: 3pt, height: 11pt, fill: theme.accent, radius: if theme.radius == 0pt { 0pt } else { 1.5pt }), text(size: 12.5pt, weight: "bold", fill: theme.primary, font: theme.font-heading)[#("Suggestions du Jour")])
                #v(2pt)
                #text(size: 8.5pt, fill: theme.muted)[#(fx-str(fx-get(data, "document.dayOfWeek")) + " " + fx-date(fx-get(data, "document.date")))]
              ]
            ]
          ]
          #if fx-truthy(fx-get(data, "menu.dailySpecials")) [
            #fx-block(id: "specials-table")[
              #fx-table(
                columns: (1.2fr, 2fr, 0.6fr,),
                headers: ("Suggestion", "Accompagnement", "Prix",),
                aligns: ("left", "left", "right",),
                striped: true,
                rows: fx-list(data, "menu.dailySpecials").map(item_0 => (
                  fx-str(fx-get(item_0, "name")),
                  fx-str(fx-get(item_0, "description")),
                  fx-money(fx-get(item_0, "price"), currency: fx-str(fx-get(data, "document.currency"), default: "EUR")),
                )),
                theme: theme,
              )
            ]
          ]
          #if fx-truthy(fx-get(data, "menu.formulas")) [
            #fx-block(id: "formulas-heading")[
              #block(width: 100%, above: 10pt, below: 5pt)[
                #stack(dir: ltr, spacing: 6pt, rect(width: 3pt, height: 11pt, fill: theme.accent, radius: if theme.radius == 0pt { 0pt } else { 1.5pt }), text(size: 12.5pt, weight: "bold", fill: theme.primary, font: theme.font-heading)[#("Formules & Menus")])
              ]
            ]
          ]
          #if fx-truthy(fx-get(data, "menu.formulas")) [
            #fx-block(id: "formulas-repeat")[
              #for item_0 in fx-list(data, "menu.formulas") [
                #fx-block(id: "formula-card")[
                  #fx-card(title: fx-str(fx-get(item_0, "name")) + " — " + fx-money(fx-get(item_0, "price"), currency: fx-str(fx-get(data, "document.currency"), default: "EUR")), eyebrow: fx-str(fx-get(item_0, "description")), accent: true, theme: theme)[
                  ]
                ]
                #v(6pt)
              ]
            ]
          ]
        ]
      ]
    ],
    [
      #fx-block(id: "menu-right-col")[
        #fx-card(theme: theme)[
          #if fx-truthy(fx-get(data, "menu.sections")) [
            #fx-block(id: "sections-repeat")[
              #for item_0 in fx-list(data, "menu.sections") [
                #fx-block(id: "section-heading")[
                  #block(width: 100%, above: 10pt, below: 5pt)[
                    #stack(dir: ltr, spacing: 6pt, rect(width: 3pt, height: 11pt, fill: theme.accent, radius: if theme.radius == 0pt { 0pt } else { 1.5pt }), text(size: 12.5pt, weight: "bold", fill: theme.primary, font: theme.font-heading)[#(fx-str(fx-get(item_0, "title")))])
                    #v(2pt)
                    #text(size: 8.5pt, fill: theme.muted)[#(fx-str(fx-get(item_0, "description")))]
                  ]
                ]
                #fx-block(id: "section-items-table")[
                  #fx-table(
                    columns: (1.2fr, 2fr, 0.6fr,),
                    headers: ("Plat", "Description", "Prix",),
                    aligns: ("left", "left", "right",),
                    striped: true,
                    rows: fx-list(item_0, "items").map(item_1 => (
                      fx-str(fx-get(item_1, "name")),
                      fx-str(fx-get(item_1, "description")),
                      fx-money(fx-get(item_1, "price"), currency: fx-str(fx-get(data, "document.currency"), default: "EUR")),
                    )),
                    theme: theme,
                  )
                ]
                #v(8pt)
              ]
            ]
          ]
        ]
      ]
    ],
  )
]

#if fx-truthy(fx-get(data, "menu.footnote")) [
  #fx-block(id: "menu-footnote")[
    #block(width: 100%)[#align(center)[#text(size: 8pt, fill: theme.muted)[#(fx-str(fx-get(data, "menu.footnote")))]]]
  ]
]

record.schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "MenuDocument",
  "type": "object",
  "required": [
    "establishment",
    "document",
    "menu"
  ],
  "properties": {
    "establishment": {
      "type": "object",
      "description": "Informations générales sur l'établissement.",
      "required": [
        "name",
        "address"
      ],
      "properties": {
        "name": {
          "type": "string",
          "description": "Nom de l'établissement.",
          "example": "Le Bistrot du Marché"
        },
        "category": {
          "type": "string",
          "description": "Type d'établissement (bistrot, brasserie, restaurant gastronomique, etc.).",
          "example": "Bistrot traditionnel"
        },
        "address": {
          "type": "string",
          "description": "Adresse postale complète.",
          "example": "14 Rue des Halles, 69001 Lyon"
        },
        "phone": {
          "type": "string",
          "description": "Numéro de téléphone pour les réservations.",
          "example": "+33 4 78 12 34 56"
        },
        "email": {
          "type": "string",
          "format": "email",
          "description": "Adresse e-mail de contact.",
          "example": "contact@bistrotdumarche.fr"
        },
        "website": {
          "type": "string",
          "format": "uri",
          "description": "Site web officiel de l'établissement.",
          "example": "https://www.bistrotdumarche.fr"
        },
        "openingHours": {
          "type": "string",
          "description": "Horaires d'ouverture affichés sur le menu.",
          "example": "Du mardi au dimanche, 12h00-14h30 et 19h00-22h30"
        }
      }
    },
    "document": {
      "type": "object",
      "description": "Métadonnées du document de menu.",
      "required": [
        "title",
        "date",
        "dayOfWeek",
        "service",
        "status",
        "currency"
      ],
      "properties": {
        "title": {
          "type": "string",
          "description": "Titre principal du menu.",
          "example": "Menu du Jour"
        },
        "subtitle": {
          "type": "string",
          "description": "Sous-titre ou accroche saisonnière.",
          "example": "Cuisine de saison et produits locaux"
        },
        "reference": {
          "type": "string",
          "description": "Référence interne du document.",
          "example": "MENU-2026-1122"
        },
        "status": {
          "type": "string",
          "enum": [
            "BROUILLON",
            "PUBLIE",
            "ARCHIVE"
          ],
          "description": "Statut de publication du menu.",
          "example": "PUBLIE"
        },
        "date": {
          "type": "string",
          "format": "date",
          "description": "Date d'application du menu.",
          "example": "2026-11-22"
        },
        "dayOfWeek": {
          "type": "string",
          "enum": [
            "Lundi",
            "Mardi",
            "Mercredi",
            "Jeudi",
            "Vendredi",
            "Samedi",
            "Dimanche"
          ],
          "description": "Jour de la semaine correspondant au menu.",
          "example": "Dimanche"
        },
        "service": {
          "type": "string",
          "enum": [
            "Déjeuner",
            "Dîner",
            "Brunch",
            "Journée complète"
          ],
          "description": "Service concerné par ce menu.",
          "example": "Déjeuner"
        },
        "currency": {
          "type": "string",
          "enum": [
            "EUR",
            "CHF",
            "CAD"
          ],
          "description": "Devise utilisée pour l'affichage des prix.",
          "example": "EUR"
        },
        "summary": {
          "type": "string",
          "description": "Mot du chef ou présentation courte.",
          "example": "Tous nos plats sont préparés sur place à partir de produits frais du marché."
        }
      }
    },
    "menu": {
      "type": "object",
      "description": "Contenu détaillé de la carte et des formules.",
      "required": [
        "sections"
      ],
      "properties": {
        "dailySpecials": {
          "type": "array",
          "description": "Suggestions ou plats du jour mis en avant.",
          "items": {
            "type": "object",
            "required": [
              "name",
              "price",
              "isAvailable"
            ],
            "properties": {
              "name": {
                "type": "string",
                "description": "Nom de la suggestion.",
                "example": "Blanquette de veau à l'ancienne"
              },
              "description": {
                "type": "string",
                "description": "Accompagnements et détails de préparation.",
                "example": "Riz basmati parfumé et légumes glacés"
              },
              "price": {
                "type": "number",
                "description": "Prix TTC.",
                "example": 19.5
              },
              "isAvailable": {
                "type": "boolean",
                "description": "Indique si le plat est actuellement disponible.",
                "example": true
              }
            }
          }
        },
        "formulas": {
          "type": "array",
          "description": "Formules et menus à prix fixe.",
          "items": {
            "type": "object",
            "required": [
              "name",
              "price",
              "includedCourses"
            ],
            "properties": {
              "name": {
                "type": "string",
                "description": "Intitulé de la formule.",
                "example": "Formule Bistrot"
              },
              "description": {
                "type": "string",
                "description": "Conditions ou précisions sur la formule.",
                "example": "Servie uniquement le midi hors jours fériés"
              },
              "price": {
                "type": "number",
                "description": "Prix TTC de la formule.",
                "example": 24
              },
              "includedCourses": {
                "type": "array",
                "description": "Liste des services inclus dans la formule.",
                "items": {
                  "type": "string"
                }
              }
            }
          }
        },
        "sections": {
          "type": "array",
          "description": "Catégories principales du menu (Entrées, Plats, Desserts, Boissons).",
          "items": {
            "type": "object",
            "required": [
              "title",
              "items"
            ],
            "properties": {
              "title": {
                "type": "string",
                "description": "Nom de la catégorie.",
                "example": "Entrées"
              },
              "description": {
                "type": "string",
                "description": "Sous-titre optionnel de la catégorie.",
                "example": "Pour bien commencer votre repas"
              },
              "items": {
                "type": "array",
                "description": "Liste des plats ou boissons de cette catégorie.",
                "items": {
                  "type": "object",
                  "required": [
                    "name",
                    "price",
                    "isAvailable"
                  ],
                  "properties": {
                    "name": {
                      "type": "string",
                      "description": "Nom du plat ou de la boisson.",
                      "example": "Velouté de potimarron aux éclats de châtaignes"
                    },
                    "description": {
                      "type": "string",
                      "description": "Description des ingrédients et de la préparation.",
                      "example": "Crème fraîche fermière et croûtons dorés à l'ail"
                    },
                    "price": {
                      "type": "number",
                      "description": "Prix TTC.",
                      "example": 9.5
                    },
                    "isAvailable": {
                      "type": "boolean",
                      "description": "Disponibilité en salle.",
                      "example": true
                    },
                    "dietaryTags": {
                      "type": "array",
                      "description": "Mentions alimentaires particulières.",
                      "items": {
                        "type": "string",
                        "enum": [
                          "Végétarien",
                          "Végan",
                          "Sans gluten",
                          "Sans lactose",
                          "Fait maison"
                        ]
                      }
                    },
                    "allergens": {
                      "type": "array",
                      "description": "Allergènes majeurs présents dans le plat.",
                      "items": {
                        "type": "string"
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "footnote": {
          "type": "string",
          "description": "Mentions légales ou informations complémentaires en pied de page.",
          "example": "Prix nets en euros, service compris. Liste complète des allergènes disponible sur demande."
        }
      }
    }
  }
}

